/// <summary>
/// Business event triggered when a free text invoice is posted.
/// </summary>
[BusinessEvents(classStr(AAXFreeTextInvoicePostedBusinessEventContract), 'FreeTextInvoicePostedBusinessEventName', 'FreeTextInvoicePostedBusinessEventDescription', ModuleAxapta::Customer)]
public final class AAXFreeTextInvoicePostedBusinessEvent extends BusinessEventsBase
{
    private CustInvoiceJour custInvoiceJour;

}

Method.Source:
/// <summary>
/// Gets or sets the source CustInvoiceJour for building the event contract.
/// </summary>
private CustInvoiceJour parmCustInvoiceJour(CustInvoiceJour _custInvoiceJour = custInvoiceJour)
{
    custInvoiceJour = _custInvoiceJour;

    return custInvoiceJour;
}

/// <summary>
/// Creates a new <c>AAXFreeTextInvoicePostedBusinessEvent</c> instance from the specified <c>CustInvoiceJour</c> record.
/// </summary>
/// <param name="_custInvoiceJour">The source CustInvoiceJour record.</param>
/// <returns>A new instance of <c>AAXFreeTextInvoicePostedBusinessEvent</c>.</returns>
public static AAXFreeTextInvoicePostedBusinessEvent newFromCustInvoiceJour(CustInvoiceJour _custInvoiceJour)
{
    AAXFreeTextInvoicePostedBusinessEvent businessEvent = new AAXFreeTextInvoicePostedBusinessEvent();
    businessEvent.parmCustInvoiceJour(_custInvoiceJour);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXFreeTextInvoicePostedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXFreeTextInvoicePostedBusinessEventContract::newFromCustInvoiceJour(custInvoiceJour);
}
